// Embedded AutoCAD dynamic-block regression data.
// Source drawings are from ACadSharp samples/dynamic-blocks (MIT).
// Derived drawings were saved by AutoCAD 2025; see the original fixture attribution.

use std::io::Read;

fn decode_base64(input: &str) -> Vec<u8> {
    let mut values = Vec::new();
    let mut buffer = 0u32;
    let mut bits = 0u8;
    for byte in input.bytes().filter(|b| !b.is_ascii_whitespace()) {
        let value = match byte {
            b'A'..=b'Z' => byte - b'A',
            b'a'..=b'z' => byte - b'a' + 26,
            b'0'..=b'9' => byte - b'0' + 52,
            b'+' => 62,
            b'/' => 63,
            b'=' => break,
            _ => continue,
        } as u32;
        buffer = (buffer << 6) | value;
        bits += 6;
        while bits >= 8 {
            bits -= 8;
            values.push((buffer >> bits) as u8);
            buffer &= (1u32 << bits) - 1;
        }
    }
    values
}

fn gunzip(encoded: &str) -> Vec<u8> {
    let compressed = decode_base64(encoded);
    let mut decoder = flate2::read::GzDecoder::new(compressed.as_slice());
    let mut bytes = Vec::new();
    decoder
        .read_to_end(&mut bytes)
        .expect("embedded DWG fixture should decompress");
    bytes
}

