pub fn fixture(name: &str) -> Vec<u8> {
    let encoded = match name {
        "BLOCKALIGNMENTPARAMETER" => BLOCKALIGNMENTPARAMETER,
        "BLOCKBASEPOINTPARAMETER" => BLOCKBASEPOINTPARAMETER,
        "BLOCKFLIPPARAMETER" => BLOCKFLIPPARAMETER,
        "BLOCKLINEARPARAMETER" => BLOCKLINEARPARAMETER,
        "BLOCKLOOKUPPARAMETER" => BLOCKLOOKUPPARAMETER,
        "BLOCKPOINTPARAMETER" => BLOCKPOINTPARAMETER,
        "BLOCKPOLARPARAMETER" => BLOCKPOLARPARAMETER,
        "BLOCKROTATIONPARAMETER" => BLOCKROTATIONPARAMETER,
        "BLOCKVISIBILITYPARAMETER" => BLOCKVISIBILITYPARAMETER,
        "BLOCKXYPARAMETER" => BLOCKXYPARAMETER,
        "LOOKUP_R2004" => LOOKUP_R2004,
        "LOOKUP_REOPEN" => LOOKUP_REOPEN,
        "ROTATION_270" => ROTATION_270,
        _ => panic!("unknown embedded fixture {}", name),
    };
    gunzip(encoded)
}
